func approx(t *testing.T, got, want float64, what string) {
	t.Helper()
	if math.Abs(got-want) > 1e-6*math.Max(1, math.Abs(want)) {
		t.Fatalf("%s = %.9f, want %.9f", what, got, want)
	}
}

func TestExpectedStepsExamples(t *testing.T) {
	approx(t, expectedSteps(0, []float64{0, 1}), 0, "already there")
	approx(t, expectedSteps(7, []float64{0, 1}), 7, "sure single step")
	// A stay probability of 0.9 multiplies every step by 1/(1-0.9).
	approx(t, expectedSteps(5, []float64{0.9, 0.1}), 50, "heavy self loop")
	// From 0 with n = 1 a step of 2 overshoots and is wasted, so this is a
	// geometric wait with success probability 0.5.
	approx(t, expectedSteps(1, []float64{0, 0.5, 0.5}), 2, "overshoot wasted")
}

// The oracle is plain value iteration, which never solves for the self loop
// algebraically: it just applies the one-step update until it stops moving.
func TestExpectedStepsAgainstValueIteration(t *testing.T) {
	rng := rand.New(rand.NewSource(5))
	for trial := 0; trial < 60; trial++ {
		n := 1 + rng.Intn(15)
		m := 2 + rng.Intn(5)
		p := make([]float64, m)
		total := 0.0
		for k := range p {
			p[k] = rng.Float64()
			total += p[k]
		}
		if p[1] < 0.05*total {
			p[1] = 0.05 * total
			total += 0.05 * total
		}
		for k := range p {
			p[k] /= total
		}

		exp := make([]float64, n+1)
		for iter := 0; iter < 400000; iter++ {
			next := make([]float64, n+1)
			for i := 0; i < n; i++ {
				next[i] = 1
				for k := 0; k < m; k++ {
					dst := i + k
					if dst > n {
						dst = i
					}
					next[i] += p[k] * exp[dst]
				}
			}
			exp = next
		}
		approx(t, expectedSteps(n, p), exp[0], "value iteration")
	}
}

// 200000 positions and a 200-long step vector: the loop has to be O(n*m) and
// the closed form n/p[1] pins the self loop at scale.
func TestExpectedStepsLarge(t *testing.T) {
	p := make([]float64, 200)
	p[0], p[1] = 0.3, 0.7
	approx(t, expectedSteps(200000, p), 200000/0.7, "padded step vector")

	approx(t, expectedSteps(200000, []float64{0.5, 0.5}), 400000, "half stay")
}

