// expectedSteps returns the expected number of turns to move a token from 0 to
// n, where each turn advances by k with probability p[k] and a move that would
// overshoot n leaves the token where it is.
func expectedSteps(n int, p []float64) float64 {
	exp := make([]float64, n+1)
	for i := n - 1; i >= 0; i-- {
		// stay collects every outcome that leaves the token on i: the explicit
		// zero step, plus every step long enough to overshoot n.
		stay := p[0]
		sum := 0.0
		for k := 1; k < len(p); k++ {
			if i+k <= n {
				sum += p[k] * exp[i+k]
			} else {
				stay += p[k]
			}
		}
		exp[i] = (1 + sum) / (1 - stay)
	}
	return exp[0]
}

