func randWord(rng *rand.Rand, n, alpha int) string {
	b := make([]byte, n)
	for i := range b {
		b[i] = byte('a' + rng.Intn(alpha))
	}
	return string(b)
}

// The text is the period "abcde" repeated, so a pattern of length L occurs
// exactly at the positions congruent to its phase, and any pattern that is not
// one of the five phase words of its length cannot occur at all.
func TestCountOccurrencesLarge(t *testing.T) {
	const period = "abcde"
	const reps = 400000
	text := strings.Repeat(period, reps)
	n := len(text)

	phaseWord := func(phase, length int) string {
		b := make([]byte, length)
		for i := range b {
			b[i] = period[(phase+i)%5]
		}
		return string(b)
	}

	rng := rand.New(rand.NewSource(13))
	var pats []string
	var want []int
	for length := 3; length <= 32; length++ {
		for phase := 0; phase < 5; phase++ {
			pats = append(pats, phaseWord(phase, length))
			last := n - length
			if last < phase {
				want = append(want, 0)
				continue
			}
			want = append(want, (last-phase)/5+1)
		}
	}
	for len(pats) < 150000 {
		length := 3 + rng.Intn(30)
		p := []byte(phaseWord(rng.Intn(5), length))
		p[rng.Intn(length)] = byte('a' + rng.Intn(5))
		real := false
		for phase := 0; phase < 5; phase++ {
			if string(p) == phaseWord(phase, length) {
				real = true
			}
		}
		if real {
			continue
		}
		pats = append(pats, string(p))
		want = append(want, 0)
	}

	got := countOccurrences(text, pats)
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("pattern %d (%q, len %d) = %d, want %d", i, pats[i], len(pats[i]), got[i], want[i])
		}
	}
}

